    /** Deletes an existing conditional format rule. */
    deleteConditionalFormatRule?: GoogleSheets.DeleteConditionalFormatRuleRequest;
    /** Deletes a data source. */
    deleteDataSource?: GoogleSheets.DeleteDataSourceRequest;
    /** Deletes developer metadata */
    deleteDeveloperMetadata?: GoogleSheets.DeleteDeveloperMetadataRequest;
    /** Deletes rows or columns in a sheet. */
    deleteDimension?: GoogleSheets.DeleteDimensionRequest;
    /** Deletes a group over the specified range. */
    deleteDimensionGroup?: GoogleSheets.DeleteDimensionGroupRequest;
    /** Removes rows containing duplicate values in specified columns of a cell range. */
    deleteDuplicates?: GoogleSheets.DeleteDuplicatesRequest;
    /** Deletes an embedded object (e.g, chart, image) in a sheet. */
    deleteEmbeddedObject?: GoogleSheets.DeleteEmbeddedObjectRequest;
    /** Deletes a filter view from a sheet. */
