    /** Deletes a named range. */
    deleteNamedRange?: GoogleSheets.DeleteNamedRangeRequest;
    /** Deletes a protected range. */
    deleteProtectedRange?: GoogleSheets.DeleteProtectedRangeRequest;
    /** Deletes a range of cells from a sheet, shifting the remaining cells. */
