    /** A request for deleting a table. */
    deleteTable?: GoogleSheets.DeleteTableRequest;
    /** Duplicates a filter view. */
    duplicateFilterView?: GoogleSheets.DuplicateFilterViewRequest;
    /** Duplicates a sheet. */
    duplicateSheet?: GoogleSheets.DuplicateSheetRequest;
    /** Finds and replaces occurrences of some text with other text. */
    findReplace?: GoogleSheets.FindReplaceRequest;
    /** Inserts new rows or columns in a sheet. */
    insertDimension?: GoogleSheets.InsertDimensionRequest;
    /** Inserts new cells in a sheet, shifting the existing cells. */
    insertRange?: GoogleSheets.InsertRangeRequest;
    /** Merges cells together. */
    mergeCells?: GoogleSheets.MergeCellsRequest;
    /** Moves rows or columns to another location in a sheet. */
    moveDimension?: GoogleSheets.MoveDimensionRequest;
    /** Pastes data (HTML or delimited) into a sheet. */
