    /** Sets the basic filter on a sheet. */
    setBasicFilter?: GoogleSheets.SetBasicFilterRequest;
    /** Sets data validation for one or more cells. */
    setDataValidation?: GoogleSheets.SetDataValidationRequest;
    /** Sorts data in a range. */
