  /** The properties of the Line. When unset, these fields default to values that match the appearance of new lines created in the Slides editor. */
  export type LineProperties = {
    /** The dash style of the line. */
    dashStyle?: "DASH_STYLE_UNSPECIFIED" | "SOLID" | "DOT" | "DASH" | "DASH_DOT" | "LONG_DASH" | "LONG_DASH_DOT";
    /** The style of the arrow at the end of the line. */
    endArrow?: "ARROW_STYLE_UNSPECIFIED" | "NONE" | "STEALTH_ARROW" | "FILL_ARROW" | "FILL_CIRCLE" | "FILL_SQUARE" | "FILL_DIAMOND" | "OPEN_ARROW" | "OPEN_CIRCLE" | "OPEN_SQUARE" | "OPEN_DIAMOND";
    /** The connection at the end of the line. If unset, there is no connection. Only lines with a Type indicating it is a "connector" can have an `end_connection`. */
    endConnection?: GoogleSlides.LineConnection;
    /** The fill of the line. The default line fill matches the defaults for new lines created in the Slides editor. */
    lineFill?: GoogleSlides.LineFill;
    /** The hyperlink destination of the line. If unset, there is no link. */
    link?: GoogleSlides.Link;
    /** The style of the arrow at the beginning of the line. */
    startArrow?: "ARROW_STYLE_UNSPECIFIED" | "NONE" | "STEALTH_ARROW" | "FILL_ARROW" | "FILL_CIRCLE" | "FILL_SQUARE" | "FILL_DIAMOND" | "OPEN_ARROW" | "OPEN_CIRCLE" | "OPEN_SQUARE" | "OPEN_DIAMOND";
    /** The connection at the beginning of the line. If unset, there is no connection. Only lines with a Type indicating it is a "connector" can have a `start_connection`. */
    startConnection?: GoogleSlides.LineConnection;
    /** The thickness of the line. */
    weight?: GoogleSlides.Dimension;
  };

