export type DriveUploadInput = {
  file: File;
  requestBody?: GoogleDrive.File;
  "$.xgafv"?: "1" | "2";
  alt?: "json" | "media" | "proto";
  enforceSingleParent?: boolean;
  fields?: string;
  ignoreDefaultVisibility?: boolean;
  includeLabels?: string;
  includePermissionsForView?: string;
  keepRevisionForever?: boolean;
  ocrLanguage?: string;
  prettyPrint?: boolean;
  quotaUser?: string;
  supportsAllDrives?: boolean;
  supportsTeamDrives?: boolean;
  useContentAsIndexableText?: boolean;
};

export type DriveDownloadInput = {
  acknowledgeAbuse?: boolean;
  fileId: string;
  path: string;
  sha256?: string;
};

export type GoogleWorkspaceNamespace = {
  /** Request the employee's Google Workspace grant from Chrome Identity. */
  authorize(): Promise<{ authorized: true }>;
  drive(): GoogleDrive.Client;
  gmail(): GoogleGmail.Client;
  calendar(): GoogleCalendar.Client;
  docs(): GoogleDocs.Client;
  sheets(): GoogleSheets.Client;
  slides(): GoogleSlides.Client;
  chat(): GoogleChat.Client;
  people(): GooglePeople.Client;
};

declare global {
  interface ApplicationsNamespace {
    "google-workspace": GoogleWorkspaceNamespace;
  }
}
